from __future__ import annotations

import json
import re
from datetime import datetime
from pathlib import Path
from typing import Any

from pypdf import PdfReader


TASK_DIR = Path(__file__).resolve().parent
WORKSPACE_ROOT = Path(__file__).resolve().parents[3]
PACKAGE_ROOT = (
    WORKSPACE_ROOT
    / "event_packages"
    / "standard_event_packages"
    / "packages"
    / "CSX-118"
)


def read_json(relative_path: str) -> dict[str, Any]:
    with (PACKAGE_ROOT / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def read_pdf_text(relative_path: str) -> str:
    reader = PdfReader(str(PACKAGE_ROOT / relative_path))
    return "\n".join(page.extract_text() or "" for page in reader.pages)


def rounded(value: float, digits: int = 1) -> float:
    return round(float(value), digits)


def max_pair(times: list[str], values: list[float]) -> dict[str, Any]:
    index = max(range(len(values)), key=values.__getitem__)
    return {"time": times[index], "value": rounded(values[index])}


def min_pair(times: list[str], values: list[float]) -> dict[str, Any]:
    index = min(range(len(values)), key=values.__getitem__)
    return {"time": times[index], "value": rounded(values[index])}


def hours_between(start_iso: str, end_iso: str) -> float:
    start = datetime.fromisoformat(start_iso)
    end = datetime.fromisoformat(end_iso)
    return rounded((end - start).total_seconds() / 3600.0)


def parse_dublin_table(report_text: str) -> dict[str, Any]:
    pattern = re.compile(
        r"Dublin Airport\s*\(EIDW\).*?"
        r"(?P<pressure_time>\d{2}/\d{4})\s+"
        r"(?P<pressure_mb>\d+(?:\.\d+)?)\s+"
        r"(?P<wind_time>\d{2}/\d{4})\s+"
        r"(?P<wind_kt>\d+)\s+\(10 min\)\s+"
        r"(?P<gust_kt>\d+)",
        re.DOTALL,
    )
    match = pattern.search(report_text)
    if not match:
        raise ValueError("Dublin Airport table row was not found in report text")
    values = match.groupdict()
    return {
        "station": "Dublin Airport",
        "pressure_time": values["pressure_time"],
        "pressure_hpa": rounded(float(values["pressure_mb"])),
        "wind_time": values["wind_time"],
        "wind_kt": int(values["wind_kt"]),
        "gust_kt": int(values["gust_kt"]),
        "wind_kmh": rounded(int(values["wind_kt"]) * 1.852),
        "gust_kmh": rounded(int(values["gust_kt"]) * 1.852),
    }


def main() -> None:
    input_files = [
        "metadata/event.json",
        "data/event_reports/event_reports_001_Locked_package_evidence_report.pdf",
        "data/physical_hazard/physical_hazard_002_Open-Meteo_historical_wind_rain_point_API.json",
    ]

    event = read_json(input_files[0])
    report_text = read_pdf_text(input_files[1])
    open_meteo = read_json(input_files[2])

    hourly = open_meteo["hourly"]
    times = hourly["time"]
    peak_gust = max_pair(times, hourly["wind_gusts_10m"])
    peak_wind = max_pair(times, hourly["wind_speed_10m"])
    minimum_pressure = min_pair(times, hourly["pressure_msl"])
    max_hourly_rain = max_pair(times, hourly["precipitation"])
    rain_total = rounded(sum(hourly["precipitation"]))
    official = parse_dublin_table(report_text)

    core = {
        "classification": "wind_pressure_timing_core",
        "peak_gust_time": peak_gust["time"],
        "peak_gust_kmh": peak_gust["value"],
        "peak_wind_time": peak_wind["time"],
        "peak_wind_kmh": peak_wind["value"],
        "minimum_pressure_time": minimum_pressure["time"],
        "minimum_pressure_hpa": minimum_pressure["value"],
        "pressure_lag_hours": hours_between(
            peak_gust["time"], minimum_pressure["time"]
        ),
        "gust_to_wind_ratio": rounded(
            peak_gust["value"] / peak_wind["value"], 2
        ),
        "rainfall_total_mm": rain_total,
        "max_hourly_rain_mm": max_hourly_rain["value"],
        "official_dublin_gust_kmh": official["gust_kmh"],
        "point_minus_official_gust_kmh": rounded(
            peak_gust["value"] - official["gust_kmh"]
        ),
        "short_conclusion": (
            "Dublin records show a wind and pressure timing peak with modest rain."
